python3 << 'EOF'
import zipfile, re
from xml.etree import ElementTree as ET

NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
z = zipfile.ZipFile('budget.xlsx')
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

def col_key(ref):
    col = re.sub(r'\d', '', ref)
    return (len(col), col)

rows = []
for row in root.iter('{%s}row' % NS):
    cells = {}
    for c in row.iter('{%s}c' % NS):
        ref = c.get('r')
        t = c.get('t')
        v = c.find('{%s}v' % NS)
        is_ = c.find('{%s}is' % NS)
        if t == 'inlineStr' and is_ is not None:
            val = ''.join(x.text or '' for x in is_.iter('{%s}t' % NS))
        elif v is not None:
            val = v.text
        else:
            val = ''
        cells[ref] = val
    rows.append(cells)

for r in rows:
    items = sorted(r.items(), key=lambda kv: col_key(kv[0]))
    print(items)
EOF
